    write_serialized_records,
)
from .interfaces import ExcelParse, i_factory

FILE_OUTPUT_SUFFIXES = (".json", ".csv")
URI_SCHEMES = ("null", "stdout", "sqlite3", "postgres", "html")


def handle(e, exceptions=None, msg=None, debug=False, exit=True):
    """
    handle exceptions based on settings
    """

    if msg is None:
        msg = f"an error occurred - {e}"

    if exceptions and not isinstance(exceptions, Iterable):
        exceptions = [exceptions]

    if exceptions is None or type(e) in exceptions:
        print(msg)

        if debug:
            raise e
        elif exit:
            sys.exit(1)


@click.group()
@click.pass_context
@click.option(
    "--input",
    "-i",
    type=str,
    default="null:///",
    help="input source",
)
@click.option(
    "--output",
    "-o",
    type=str,
    default="null:///",
    help="output destination",
)
@click.option(
    "--file",
    "-f",
    type=str,
    multiple=True,
    help="file(s) or dir(s) to target",
)
@click.option(
    "--debug",
    "-d",
    is_flag=True,
    default=False,
    help="use debug mode",
)
@click.option(
    "--loose",
    "-l",
    is_flag=True,
    default=True,
    help="find tables loosely",
)
@click.option(
    "--recursive",
    "-r",
    is_flag=True,
    default=False,
    help="find files recursively",
)
@click.option(
    "--truncate",
    "-t",
    is_flag=True,
    default=True,
    help="truncate dataframe output",
)
@click.option(
    "--verbose",
    "-v",
    count=True,
    help="increase output verbosity",
)
def main(
    ctx,
    input,
    output,
    file,
    debug,
    loose,
    recursive,
    truncate,
    verbose,
):
    """
    excel parser
    """

    ctx.obj["input"] = input
    ctx.obj["output"] = output
    ctx.obj["file"] = file
    ctx.obj["debug"] = debug
    ctx.obj["loose"] = loose
    ctx.obj["recursive"] = recursive
    ctx.obj["truncate"] = truncate
    ctx.obj["verbose"] = verbose

    files = []

    # get target file(s)
    for i in file:
        if Path(i).is_dir():
            g = "**/*" if recursive else "*"
            files += Path(i).glob(g)
        elif Path(i).is_file():
            files.append(Path(i))

    ctx.obj["files"] = files

    if ctx.obj["verbose"]:
        print(f"found {len(files)} files")

    # get input and output objects
    for t in ("input", "output"):
        # a plain json/csv file path is handled by the parse command's
        # file exporter rather than the URI-based interfaces below
        if t == "output" and Path(ctx.obj[t]).suffix.lower() in FILE_OUTPUT_SUFFIXES:
            ctx.obj[f"{t}_obj"] = None
            continue

        try:
            ctx.obj[f"{t}_obj"] = i_factory(ctx.obj[t], ExcelParse)
        except ValueError as e:
            handle(e, msg=f"{t} error - {e}", debug=debug)

    # set truncate option
    if not truncate:
        # pd.set_option('display.max_colwidth', None)
        pd.set_option("display.max_rows", None)


@main.command()
@click.pass_context
@click.option(
    "--number",
    "-n",
    type=int,
    default=None,
    help="stop after n excel files",
)
@click.option(
    "--sheet",
    "-s",
    type=str,
    default=None,
    help="name of sheet to scan for",
)
@click.option(
    "--tables",
    "-t",
    is_flag=True,
    default=False,
    help="count tables in scanned sheets",
)
def scan(ctx, number, sheet, tables):
    """
    scan for excel files in target
    """

    ctx.obj["number"] = number
    ctx.obj["sheet"] = sheet
    ctx.obj["tables"] = tables

    if ctx.obj["debug"]:
        PrettyPrinter().pprint(ctx.obj)

    # process each Excel file in files
    for i, f in enumerate(ctx.obj["files"]):
        if f.is_file() and "xls" in f.name:
            try:
                e_file = pd.read_excel(
                    f,
                    sheet_name=sheet,
                    header=None,
                    index_col=None,
                )
            except Exception as e:
                msg = f"skipping {f} - {e}"
                handle(e, msg=msg, debug=ctx.obj["debug"], exit=False)
                continue

            # get basic info about Excel file
            f_size_mb = f.stat().st_size / 1_024_000
            sheets = []

            if type(e_file) is dict:
                sheets = e_file.keys()

            # build output result based on options selected
            result = f"{f.name}"

            if ctx.obj["verbose"]:
                result += f" {f_size_mb:.2f}MB"

            if sheet is not None:
                result += f" with {sheet} {e_file.shape}"

                if tables:
                    t = df_find_tables(e_file, ctx.obj["loose"])
                    result += f" containing {len(t)} tables"

                    if ctx.obj["verbose"] > 1:
                        result += f" ({t})"

            else:
                if ctx.obj["verbose"]:
                    result += f" with {len(sheets)} sheets"

                if ctx.obj["verbose"] > 1 and len(sheets):
                    result += f' {",".join(sheets)}'

            # print result
            print(result)

            if ctx.obj["debug"]:
                PrettyPrinter().pprint(e_file)

            # continue if number has not been reached
            if number is not None and i >= number:
                break


@main.command()
@click.pass_context
@click.option(
    "--sheet",
    "-s",
    type=str,
    multiple=True,
    help="name of sheet(s) to parse",
)
@click.option(
    "--serialize",
    "-z",
    is_flag=True,
    default=False,
    help="serialize table output",
)
@click.option(
    "--table",
    "-t",
    type=str,
    default=None,
    help="name of table to parse",
)
@click.option(
    "--nacount",
    type=int,
    default=0,
    help="allow for this many NA values when spanning rows and columns",
)
@click.option(
    "--exclude-nested",
    is_flag=True,
    default=False,
    help="exclude nested tables from output (only top-level tables)",
)
@click.option(
    "--sheet-filter",
    type=str,
    default=None,
    help="regex applied to sheet names; only matching tables are kept",
)
@click.option(
    "--range-filter",
    type=str,
    default=None,
    help="regex applied to each table's excel range (e.g. 'A1:B3')",
)
@click.option(
    "--type",
    "output_type",
    type=click.Choice(["json", "csv"]),
    default=None,
    help="write filtered tables to --output as json or csv",
)
def parse(
    ctx,
    sheet,
    serialize,
    table,
    nacount,
    exclude_nested,
    sheet_filter,
    range_filter,
    output_type,
):
    """
    parse table(s) found in sheet for target(s)
    """

    ctx.obj["sheet"] = sheet
    ctx.obj["serialize"] = serialize
    ctx.obj["table"] = table
    ctx.obj["na_tolerance_r"] = nacount + 1
    ctx.obj["na_tolerance_c"] = nacount + 1
    ctx.obj["sheet_filter"] = sheet_filter
    ctx.obj["range_filter"] = range_filter
    ctx.obj["output_type"] = output_type

    if ctx.obj["debug"]:
        PrettyPrinter().pprint(ctx.obj)

    # fail fast with a clear, non-zero exit on bad filter patterns instead
    # of leaking a traceback or silently skipping the filter per file
    try:
        validate_table_filters(sheet_filter, range_filter)
    except InvalidFilterPattern as e:
        handle(e, msg=f"filter error - {e}", debug=ctx.obj["debug"])

    if output_type is not None:
        output = ctx.obj["output"]
        if output.split("://")[0] in URI_SCHEMES:
            handle(
                ValueError("a file path is required"),
                msg=f"--type requires a file path via --output, got {output!r}",
                debug=ctx.obj["debug"],
            )

    records = []

    for f in ctx.obj["files"]:
        if f.is_file() and "xls" in f.name:
            print(f"{f.name}")

            try:
                for (
                    output,
                    excel_RC,
                    name,
                    s,
                ) in get_df_from_file(
                    f,
                    ctx.obj["loose"],
                    sheet,
                    table,
                    ctx.obj["na_tolerance_r"],
                    ctx.obj["na_tolerance_c"],
                    exclude_nested=exclude_nested,
                    sheet_filter=sheet_filter,
                    range_filter=range_filter,
                ):
                    if ctx.obj["verbose"]:
                        m = "{} table {} {} found at {} in {}"
                        v = (f.name, name, output.shape, excel_RC, s)
                        print(m.format(*v))

                    if serialize or output_type:
                        output = df_serialize_table(
                            output,
                            name=name,
                            sheet=s,
                            f_name=f.name,
                        )

                    if ctx.obj["debug"]:
                        PrettyPrinter().pprint(output)

                    if output_type:
                        records.extend(output)
                        continue

                    try:
                        ctx.obj["output_obj"].output(output, ctx)
                    except Exception as e:
                        msg = f'output to {ctx.obj["output"]} failed - {e}'
                        handle(e, msg=msg, debug=ctx.obj["debug"], exit=False)
                        break

            except Exception as e:
                msg = f"skipping {f} - {e}"
                handle(e, msg=msg, debug=ctx.obj["debug"], exit=False)
                continue

    if output_type:
        try:
            write_serialized_records(records, ctx.obj["output"], output_type)
        except Exception as e:
            msg = f'output to {ctx.obj["output"]} failed - {e}'
            handle(e, msg=msg, debug=ctx.obj["debug"])


@main.command()
@click.pass_context
@click.option(
    "--filter",
    "-f",
    type=str,
    nargs=2,
    multiple=True,
    help="django-style filter(s) to apply to base queryset",
)
@click.option(
    "--method",
    "-m",
    type=str,
    default="get_queryset",
    help="method to call on eparse model",
)
@click.option(
    "--serialize",
    "-z",
    is_flag=True,
    default=False,
    help="serialize query output",
)
def query(ctx, filter, method, serialize):
    """
    query eparse output
    """

    ctx.obj["filters"] = {k: v for k, v in filter}
    ctx.obj["method"] = method

    if ctx.obj["debug"]:
        PrettyPrinter().pprint(ctx.obj)

    # input data
    try:
        data = ctx.obj["input_obj"].input(method, **ctx.obj["filters"])
    except Exception as e:
        msg = f'input from {ctx.obj["input"]} failed with {e}'
        handle(e, msg=msg, debug=ctx.obj["debug"])

    if serialize:
        try:
            data = [df_normalize_data(d) for d in data.to_dict("records")]
        except Exception as e:
            msg = "serialization error (some methods can't be serialized)"
            handle(e, msg=f"{msg} - {e}", debug=ctx.obj["debug"])

    # output data
    try:
        ctx.obj["output_obj"].output(data, ctx)
    except Exception as e:
        msg = f'output to {ctx.obj["output"]} failed with {e}'
        handle(e, msg=msg, debug=ctx.obj["debug"])


@main.command()
@click.pass_context
@click.option(
    "--migration",
    "-m",
    required=True,
    type=str,
    multiple=True,
    help="database migration(s) to apply",
)
def migrate(ctx, migration):
    """
    migrate eparse table
    """

    ctx.obj["migration"] = migration

    if ctx.obj["debug"]:
        PrettyPrinter().pprint(ctx.obj)

    # apply migrations
    for _migration in ctx.obj["migration"]:
        try:
            ctx.obj["input_obj"].migrate(_migration)
            print(f"applied {_migration}")
        except Exception as e:
            handle(e, msg=f"migration error - {e}", debug=ctx.obj["debug"])


